-- Owned event references, deterministic rerolls and partition access boundaries.
select no_plan();
select tests.create_operations_fixture();
select tests.act_as('signed_in_shopper');
select lives_ok($$select public.track_event('scan','90000000-0000-0000-0000-000000000001','{"qr_code_id":"95000000-0000-0000-0000-000000000001"}','visit')$$,'shopper tracks matching QR');
select throws_ok($$select public.track_event('unknown','90000000-0000-0000-0000-000000000001')$$,'23514',null,'unknown event refused');
select throws_ok($$select public.track_event('scan','90000000-0000-0000-0000-000000000001','{"organisation_id":"10000000-0000-0000-0000-000000000002"}')$$,'23514',null,'caller cannot supply tenancy');
select throws_ok($$select public.track_event('scan','90000000-0000-0000-0000-000000000001','{"qr_code_id":"95000000-0000-0000-0000-000000000002"}')$$,'23514',null,'QR from another retailer refused');
select throws_ok($$select public.track_event('play','90000000-0000-0000-0000-000000000002','{"show_id":"93000000-0000-0000-0000-000000000001"}')$$,'23514',null,'foreign retailer show refused');
select throws_ok($$select public.track_event('plan_pick','90000000-0000-0000-0000-000000000002','{"plan_session_id":"a0000000-0000-0000-0000-000000000002"}')$$,'23514',null,'another shopper session refused');
select throws_ok($$select public.track_event('list_add','90000000-0000-0000-0000-000000000001','{}',null,'{"list_id":"a2000000-0000-0000-0000-000000000002"}')$$,'23514',null,'another shopper list refused');
select throws_ok($$select public.track_event('list_add','90000000-0000-0000-0000-000000000001','{}',null,'{"email":"personal@example.test"}')$$,'23514',null,'arbitrary personal props refused');
select throws_ok($$select public.track_event('scan','90000000-0000-0000-0000-000000000001','{}',repeat('x',129))$$,'23514',null,'overlong session identifier refused');
select lives_ok($$select public.track_event('plan_start','90000000-0000-0000-0000-000000000001','{"plan_session_id":"a0000000-0000-0000-0000-000000000001"}')$$,'owned plan tracked');
select lives_ok($$select public.track_event('list_redeem','90000000-0000-0000-0000-000000000001','{}',null,'{"list_id":"a2000000-0000-0000-0000-000000000003"}')$$,'owned redeemed list tracked');
reset role;
select is((select organisation_id from public.events where session_key = 'visit'),'10000000-0000-0000-0000-000000000001'::uuid,'organisation derived from store');
select is((select campaign_id from public.events where session_key = 'visit'),'94000000-0000-0000-0000-000000000001'::uuid,'campaign derived from QR');
select is((select shopper_id from public.events where session_key = 'visit'),tests.get_supabase_uid('signed_in_shopper'),'shopper is server identity');
select is((select props->>'list_value_minor' from public.events where type = 'list_redeem'),'2500','value derived from list snapshot');
select lives_ok($$select private.rollup_events(now() - interval '3 hours',now() + interval '1 second')$$,'rollup applies');
select is((select sum(value) from public.metrics_daily where organisation_id = '10000000-0000-0000-0000-000000000001' and metric = 'scans'),3::numeric,'daily scan count includes older raw event');
select is((select sum(value) from public.metrics_daily where metric = 'list_value_minor'),2500::numeric,'daily list value rolled up');
select lives_ok($$select private.rollup_events(now() - interval '3 hours',now() + interval '1 second')$$,'rollup replay applies');
select is((select sum(value) from public.metrics_daily where organisation_id = '10000000-0000-0000-0000-000000000001' and metric = 'scans'),3::numeric,'rollup replay does not double count');
insert into public.metrics_daily(day,organisation_id,metric,value) values (current_date,'10000000-0000-0000-0000-000000000001','nulls',1);
select throws_ok($$insert into public.metrics_daily(day,organisation_id,metric,value) values (current_date,'10000000-0000-0000-0000-000000000001','nulls',1)$$,'23505',null,'null dimensions are unique');
select throws_ok($$select private.rollup_events(now(),now())$$,'23514',null,'empty rollup interval refused');
select ok((select count(*) > 0 from pg_inherits where inhparent = 'public.events'::regclass),'event partitions exist');
select ok((select bool_and(relation.relrowsecurity) from pg_inherits as child join pg_class as relation on relation.oid = child.inhrelid where child.inhparent = 'public.events'::regclass),'all event partitions have RLS');
select ok((select bool_and(not has_table_privilege('authenticated',child.inhrelid,'SELECT')) from pg_inherits as child where child.inhparent = 'public.events'::regclass),'no direct partition reads for API users');
select is((select retention from partman.part_config where parent_table = 'public.events'),'25 months','raw retention configured');
select private.maintain_event_partitions();
select is(current_setting('search_path'),'public, extensions','maintenance preserves caller search path');
select pass('partition maintenance rerunnable');
update public.rate_limit_buckets set tokens = 0,refilled_at = clock_timestamp() where key = 'event:' || tests.get_supabase_uid('signed_in_shopper');
select tests.act_as('signed_in_shopper');
select throws_ok($$select public.track_event('scan','90000000-0000-0000-0000-000000000001')$$,'P0001','Event rate limit exceeded','exhausted event budget refused');
reset role;
select tests.act_as('anonymous_shopper');
select lives_ok($$select public.track_event('scan','90000000-0000-0000-0000-000000000002')$$,'Supabase anonymous shopper tracks an event');
reset role;
select tests.act_as_public();
select ok(not has_function_privilege(current_user,'public.track_event(text,uuid,jsonb,text,jsonb)','EXECUTE'),'public caller has no tracking capability without Auth identity');
reset role;
select throws_ok($$update public.events set type = 'play'$$,'23514',null,'backend cannot rewrite raw facts');
select throws_ok($$delete from public.events$$,'23514',null,'raw retention uses partitions rather than row deletion');
select lives_ok($$update public.events set shopper_id = null$$,'raw shopper IDs can be anonymised');
select throws_ok($$select private.rollup_events(now() - interval '26 months',now())$$,'23514',null,'rollup cannot erase aggregates beyond raw retention');
insert into public.metrics_hourly(hour,organisation_id,metric,value) values (now() - interval '91 days','10000000-0000-0000-0000-000000000001','stale',1);
select private.rollup_events(now() - interval '1 hour',now());
select is((select count(*) from public.metrics_hourly where metric = 'stale'),0::bigint,'hourly retention clears old heatmap data');
select * from finish();
